  'cannot-sign-heading' => 'किन दस्तावेजों पर डिजिटल हस्ताक्षर नहीं किए जा सकते',
  'cannot-sign-para1' => 'इलेक्ट्रॉनिक हस्ताक्षर सभी दस्तावेज़ प्रकारों के लिए मान्य नहीं हैं। निम्नलिखित श्रेणियों में आम तौर पर साक्ष्य हस्तलिखित हस्ताक्षर, नोटरीकरण, या विशिष्ट औपचारिक प्रक्रियाओं की आवश्यकता होती है: वसीयत और वसीयतनामा, गोद लेने के कागजात, कुछ न्यायालयों में कुछ संपत्ति हस्तांतरण दस्तावेज़, अदालत के आदेश, और चेक और वचन पत्र जैसे परक्राम्य उपकरण।',
  'cannot-sign-para2' => 'यदि आप अनिश्चित हैं कि आपके अधिकार क्षेत्र में किसी विशिष्ट दस्तावेज़ के लिए इलेक्ट्रॉनिक हस्ताक्षर कानूनी रूप से वैध है या नहीं, तो इस पर भरोसा करने से पहले कानूनी सलाह लें। यह अंतरराष्ट्रीय अनुबंधों के लिए विशेष रूप से महत्वपूर्ण है जहां कई देशों के कानून एक साथ लागू हो सकते हैं।',
  'conclusion-heading' => 'निष्कर्ष',
  'conclusion-para1' => 'डिजिटल पीडीएफ हस्ताक्षर परिपक्व, कानूनी और हर प्रमुख डिवाइस पर मुफ्त में उपलब्ध है। रोजमर्रा के व्यावसायिक दस्तावेज़ों के लिए, Adobe Acrobat Reader का फ़िल और साइन फ़ीचर या आपके डिवाइस के अंतर्निहित टूल दो मिनट से कम समय में काम संभाल लेते हैं। उच्च-मूल्य वाले अनुबंधों या दस्तावेज़ों के लिए जिन्हें ऑडिट ट्रेल की आवश्यकता होती है, डॉक्यूसाइन और एडोब साइन उन स्थितियों के लिए आवश्यक अतिरिक्त सुरक्षा और दस्तावेज़ीकरण प्रदान करते हैं।',
  'conclusion-para2' => 'यदि आपको फॉर्म फ़ील्ड जोड़कर हस्ताक्षर करने के लिए एक पीडीएफ तैयार करने की आवश्यकता है, तो पीडीएफ को भरने योग्य कैसे बनाएं, इस बारे में मार्गदर्शिका देखें। भेजने से पहले हस्ताक्षरित पीडीएफ को संपीड़ित करने के लिए, पीडीएफटूल्स पर मुफ्त संपीड़न उपकरण का उपयोग करें।',
  'faqs-heading' => 'अक्सर पूछे जाने वाले प्रश्नों',
  'faq1-question' => 'क्या डिजिटल हस्ताक्षर कानूनी रूप से बाध्यकारी हैं?',
  'faq1-answer' => 'अधिकांश देशों में, हाँ. ईयू ईआईडीएएस विनियमन, यूएस ईएसआईएन अधिनियम और यूईटीए, यूके इलेक्ट्रॉनिक संचार अधिनियम, और अधिकांश न्यायालयों में समकक्ष कानून अधिकांश वाणिज्यिक समझौतों के लिए इलेक्ट्रॉनिक हस्ताक्षर को कानूनी वैधता देते हैं। मुख्य आवश्यकता हस्ताक्षर करने के इरादे का प्रमाण है, जिसे ऊपर वर्णित सभी विधियां संतुष्ट करती हैं।',
  'faq2-question' => 'यदि दस्तावेज़ पर हस्ताक्षर करने के बाद उसे संशोधित किया जाता है तो क्या होगा?',
  'faq2-answer' => 'एक छवि के रूप में रखे गए एक साधारण इलेक्ट्रॉनिक हस्ताक्षर के साथ, दस्तावेज़ को बिना पता लगाए संशोधित किया जा सकता है। डॉक्यूसाइन या एडोब साइन जैसी सेवा से क्रिप्टोग्राफ़िक डिजिटल हस्ताक्षर के साथ, कोई भी संशोधन हस्ताक्षर को तुरंत अमान्य कर देता है और पीडीएफ पाठक एक चेतावनी प्रदर्शित करते हैं। उन दस्तावेज़ों के लिए जहां अखंडता महत्वपूर्ण है, ऐसी सेवा का उपयोग करें जो क्रिप्टोग्राफ़िक हस्ताक्षर प्रदान करती है।',
  'faq3-question' => 'क्या मैं पासवर्ड से सुरक्षित पीडीएफ पर हस्ताक्षर कर सकता हूँ?',
  'faq3-answer' => 'आम तौर पर नहीं, पहले सही पासवर्ड डाले बिना नहीं। एक बार जब आप दस्तावेज़ को उसके पासवर्ड से अनलॉक कर देते हैं, तो आप हस्ताक्षर करने के लिए आगे बढ़ सकते हैं। कुछ संरक्षित पीडीएफ में ऐसी अनुमतियाँ होती हैं जो पासवर्ड दर्ज करने के बाद भी हस्ताक्षर करने को प्रतिबंधित करती हैं, ऐसी स्थिति में आपको दस्तावेज़ निर्माता को एक अनलॉक संस्करण प्रदान करने की आवश्यकता होती है।',
  'faq4-question' => 'मैं किसी अन्य व्यक्ति से पीडीएफ पर हस्ताक्षर करने का अनुरोध कैसे करूँ?',
  'faq4-answer' => 'डॉक्यूसाइन, एडोब साइन और ड्रॉपबॉक्स साइन जैसी सेवाएं आपको एक पीडीएफ अपलोड करने, यह निर्दिष्ट करने की अनुमति देती हैं कि प्रत्येक व्यक्ति को कहां हस्ताक्षर करने की आवश्यकता है, और ईमेल द्वारा हस्ताक्षर अनुरोध भेजने की अनुमति देती है। प्रत्येक प्राप्तकर्ता एक लिंक पर क्लिक करता है, इलेक्ट्रॉनिक रूप से हस्ताक्षर करता है, और जब सभी ने हस्ताक्षर कर दिए हैं तो सभी पक्षों को स्वचालित रूप से पूरा दस्तावेज़ प्राप्त होता है।',
  'a'=>'<a href="' . localized_route('compress-pdf') . '">हस्ताक्षरित पीडीएफ को संपीड़ित करना</a>',
  'b' => 'भेजने से पहले, PDFTools पर निःशुल्क संपीड़न उपकरण का उपयोग करें।',
);
